/** Common utilities used for OT Delta realtime collaborative editing. */
import { $isSomeVerseNode } from "../../../nodes/usj/node-react.utils";
import { validOTEmbedTypes } from "./rich-text-ot.model";
import { $dfsIterator, $findMatchingParent } from "@lexical/utils";
import { $getNodeByKey, $getState, $isElementNode, $isTextNode, } from "lexical";
