import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  $findMatchingParent,
  $getNearestBlockElementAncestorOrThrow,
  mergeRegister,
} from "@lexical/utils";
import {
  $getEditor,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  $isTextNode,
  $setCompositionKey,
  COMMAND_PRIORITY_HIGH,
  COMMAND_PRIORITY_LOW,
  CONTROLLED_TEXT_INSERTION_COMMAND,
  DELETE_CHARACTER_COMMAND,
  $hasUpdateTag,
  ElementNode,
  LexicalNode,
  PASTE_COMMAND,
  PasteCommandType,
  PointType,
  RangeSelection,
  SELECTION_INSERT_CLIPBOARD_NODES_COMMAND,
  TextNode,
} from "lexical";
import { $isNoteNode, NBSP, NoteNode, ZWSP } from "shared";
import {
  $isPlainProse,
  $selectionContainsVerseMarker,
  $shouldBlockSelectionReplacement,
  CONFIRMED_DELETE_TAG,
  StructureProtectionMode,
} from "shared-react";
import { useEffect } from "react";

/**
 * Typing over, or deleting, a range that spans more than one text within one paragraph — across a
 * char span's edge, or across a collapsed note. Lexical's own `RangeSelection.insertText` moves the
 * content after the range's last text to after its first text, and first moves a start at a text's
 * end into the inline element that follows. So the text after an enclosing span would be pulled
 * into the span the range starts in (saved in the wrong place, with the wrong style), and a range
 * starting just before a collapsed note would put the typed text, and the text after the range,
 * into the note, which is then removed for having lost its caller — losing both. Here only the
 * selected bytes go: the two edge texts are cut, the nodes between them removed, and each span or
 * note the removal leaves empty with them.
 *
 * Only in the views whose markers are hidden: there a span is its content alone, with no glyph of
 * its own that the range could take. The marker-edit engine owns Standard view's range edits.
 *
 * A composition (an input method or a dead key) over such a range starts with Lexical inserting a
 * placeholder over the range, which is handled here like any typed text. The rest of the composition
 * replaces the placeholder in the text the range started in. Nothing goes earlier than Lexical's own
 * start of a composition would take it.
 *
 * A paste over such a range goes the same way. Prose that arrives as nodes replaces the range as
 * typed text does. Plain text, which Lexical inserts with that same `insertText`, has the range
 * removed first and is then Lexical's to insert at the caret, as it holds line breaks and tabs that
 * typed text does not. Any other payload is inserted with `insertNodes`, which does not have this
 * problem. Plain text waits at `COMMAND_PRIORITY_LOW`, behind every handler that can refuse the paste,
 * so a refused paste has removed nothing.
 *
 * Mounted ahead of `StructureKeyboardPlugin`, so it claims these commands first. It therefore
 * leaves a range that plugin judges to it, which is what keeps structure protection in force for
 * edits that arrive with no keydown (an input method, macOS Ctrl+H): under `"protected"` a range
 * that spans a paragraph boundary or holds a verse marker is left alone, and under `"guarded"` a
 * delete of a range holding a verse marker is left alone until the user has confirmed it (the
 * confirmed delete carries {@link CONFIRMED_DELETE_TAG}). Typing over such a range under
 * `"guarded"` is not held back.
 *
 * @param structureProtectionMode - How the host protects document structure. Defaults to `"off"`.
 */
export function InlineRangeEditPlugin({
  structureProtectionMode = "off",
}: {
  structureProtectionMode?: StructureProtectionMode;
}): null {
  const [editor] = useLexicalComposerContext();
  useEffect(
    () =>
      mergeRegister(
        editor.registerCommand(
          CONTROLLED_TEXT_INSERTION_COMMAND,
          (payload) => {
            const text = typeof payload === "string" ? payload : payload.data;
            if (typeof text !== "string") return false;
            if ($getEditor().isComposing())
              return (
                COMPOSITION_PLACEHOLDERS.includes(text) &&
                $replaceInlineRange(text, structureProtectionMode, "compositionPlaceholder")
              );
            return $replaceInlineRange(text, structureProtectionMode);
          },
          COMMAND_PRIORITY_HIGH,
        ),
        editor.registerCommand(
          DELETE_CHARACTER_COMMAND,
          () =>
            !$getEditor().isComposing() &&
            $replaceInlineRange("", structureProtectionMode, "delete"),
          COMMAND_PRIORITY_HIGH,
        ),
        editor.registerCommand(
          SELECTION_INSERT_CLIPBOARD_NODES_COMMAND,
          ({ nodes }) =>
            nodes.length > 0 &&
            nodes.every($isPlainProse) &&
            $replaceInlineRange(
              nodes.map((node) => node.getTextContent()).join(""),
              structureProtectionMode,
            ),
          COMMAND_PRIORITY_HIGH,
        ),
        editor.registerCommand(
          PASTE_COMMAND,
          (event) => {
            if (isPlainTextPaste(event))
              $replaceInlineRange("", structureProtectionMode, "caretForPaste");
            return false;
          },
          COMMAND_PRIORITY_LOW,
        ),
      ),
    [editor, structureProtectionMode],
  );
  return null;
}

/**
 * What Lexical inserts over a range when a composition starts, its private `COMPOSITION_START_CHAR`:
 * a zero-width space, or a no-break space in the browsers that need one. A composing insertion of
 * anything else is the composition itself, which stays with Lexical.
 */
const COMPOSITION_PLACEHOLDERS = [ZWSP, NBSP];

/**
 * Whether Lexical will insert this paste as plain text: it holds text, and neither of the flavors
 * Lexical prefers. It treats html identical to the plain text as plain text.
 */
function isPlainTextPaste(event: PasteCommandType): boolean {
  const data = "clipboardData" in event ? event.clipboardData : undefined;
  if (!data || data.getData("application/x-lexical-editor")) return false;
  const text = data.getData("text/plain");
  const html = data.getData("text/html");
  return !!text && (!html || html === text);
}

/**
 * What {@link $replaceInlineRange} is replacing the range for:
 *
 * - `edit`: `text` is the whole of the edit.
 * - `delete`: a character delete; `text` is empty. It differs from `edit` only in that, under
 *   `"guarded"`, a range holding a verse marker is left to the two-step confirm.
 * - `compositionPlaceholder`: `text` is the placeholder a composition starts with. Lexical has already
 *   put the composition on the range's anchor, which may be in another text, so it moves to the text
 *   holding the placeholder here: `TextNode.select` moves it only while the selection is still on
 *   that anchor, which removing the range can change. The selection covers the placeholder, as
 *   Lexical's own insertion leaves it, for the composed text to replace.
 * - `caretForPaste`: a paste is about to be inserted at the caret, in the same update, so the caret
 *   stays in the start text even if nothing is left of it.
 */
type InlineRangeReplacement = "edit" | "delete" | "compositionPlaceholder" | "caretForPaste";

/** A text and an offset in it: one end of the range. */
interface Edge {
  node: TextNode;
  offset: number;
}

/** The collapsed note `node` is shown in, if any. */
function $collapsedNoteOf(node: LexicalNode): NoteNode | undefined {
  return (
    $findMatchingParent(
      node,
      (at): at is NoteNode => $isNoteNode(at) && at.getIsCollapsed() === true,
    ) ?? undefined
  );
}

/**
 * `point` as an edge text. A collapsed note shows only its caller, so a point Lexical resolved into
 * one — it moves a range's start at a text's end into the inline element after it, and its end
 * at a text's start into the one before — is put back at the text on that side of the note. An
 * element point is at the text beside it.
 */
function $edgeText(point: PointType, side: "start" | "end"): Edge | undefined {
  const node = point.getNode();
  const note = $collapsedNoteOf(node);
  if (note) {
    const beside = side === "start" ? note.getPreviousSibling() : note.getNextSibling();
    if (!$isTextNode(beside)) return undefined;
    return { node: beside, offset: side === "start" ? beside.getTextContentSize() : 0 };
  }
  if (point.type === "text") return $isTextNode(node) ? { node, offset: point.offset } : undefined;
  if (!$isElementNode(node)) return undefined;
  const before = node.getChildAtIndex(point.offset - 1);
  const after = node.getChildAtIndex(point.offset);
  if ($isTextNode(before)) return { node: before, offset: before.getTextContentSize() };
  if ($isTextNode(after)) return { node: after, offset: 0 };
  return undefined;
}

/** The selection's two edge texts, in document order, when it is a range over more than one text
 * of one paragraph; `undefined` for any other selection. */
function $inlineRangeEdges(selection: RangeSelection): [start: Edge, end: Edge] | undefined {
  if (selection.isCollapsed()) return undefined;
  const [startPoint, endPoint] = selection.isBackward()
    ? [selection.focus, selection.anchor]
    : [selection.anchor, selection.focus];
  const start = $edgeText(startPoint, "start");
  const end = $edgeText(endPoint, "end");
  if (!start || !end || start.node.is(end.node)) return undefined;
  if (start.node.getMode() !== "normal" || end.node.getMode() !== "normal") return undefined;
  if (!start.node.isBefore(end.node)) return undefined;
  const block = $getNearestBlockElementAncestorOrThrow(start.node);
  if (!block.is($getNearestBlockElementAncestorOrThrow(end.node))) return undefined;
  return [start, end];
}

/** Remove `element` and each inline ancestor it leaves empty, when it is an empty inline element. */
function $removeIfEmptyInline(element: ElementNode | null): void {
  let current: ElementNode | null = element;
  while (current && current.isInline() && current.isAttached() && current.getChildrenSize() === 0) {
    const parent: ElementNode | null = current.getParent();
    current.remove();
    current = parent;
  }
}

/**
 * Replace the selected range with `text`, when it is one {@link $inlineRangeEdges} takes.
 *
 * @param text - What goes in place of the range.
 * @param structureProtectionMode - Decides which ranges are left to `StructureKeyboardPlugin`.
 * @param purpose - What the replacement is for.
 */
function $replaceInlineRange(
  text: string,
  structureProtectionMode: StructureProtectionMode,
  purpose: InlineRangeReplacement = "edit",
): boolean {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) return false;
  if (structureProtectionMode === "protected" && $shouldBlockSelectionReplacement(selection))
    return false;
  if (
    structureProtectionMode === "guarded" &&
    purpose === "delete" &&
    !$hasUpdateTag(CONFIRMED_DELETE_TAG) &&
    $selectionContainsVerseMarker(selection)
  )
    return false;
  const edges = $inlineRangeEdges(selection);
  if (!edges) return false;
  const [start, end] = edges;
  if (purpose === "compositionPlaceholder") $setCompositionKey(start.node.getKey());
  // A deletion of both edge texts whole leaves no text to hold the caret, so Lexical's own path,
  // which deletes such a range correctly, places it. Typed text holds it in the start text.
  if (
    text === "" &&
    (purpose === "edit" || purpose === "delete") &&
    start.offset === 0 &&
    end.offset === end.node.getTextContentSize()
  )
    return false;
  const emptied = new Set<ElementNode | null>([start.node.getParent(), end.node.getParent()]);
  // The leaves wholly inside the range; an element whose content all is goes with its content.
  const inside = start.node
    .getNodesBetween(end.node)
    .filter((node) => !node.is(start.node) && !node.is(end.node) && !$isElementNode(node));
  for (const node of inside) {
    emptied.add(node.getParent());
    node.remove();
  }
  const endNode = end.node.spliceText(0, end.offset, "");
  const startNode = start.node.spliceText(
    start.offset,
    start.node.getTextContentSize() - start.offset,
    text,
  );
  if (purpose === "compositionPlaceholder")
    startNode.select(start.offset, start.offset + text.length);
  else if (purpose === "caretForPaste" || startNode.getTextContentSize() > 0)
    startNode.select(start.offset + text.length, start.offset + text.length);
  else {
    endNode.select(0, 0);
    emptied.add(startNode.getParent());
    startNode.remove();
  }
  if (endNode.getTextContentSize() === 0 && !endNode.isSelected()) {
    emptied.add(endNode.getParent());
    endNode.remove();
  }
  emptied.forEach($removeIfEmptyInline);
  return true;
}
