import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useEffect } from "react";
export function TextDirectionPlugin({ textDirection }) {
    const [editor] = useLexicalComposerContext();
    useTextDirection(editor, textDirection);
    return null;
}
function useTextDirection(editor, textDirection) {
    useEffect(() => {
        updateTextDirection(editor, textDirection);
        return editor.registerUpdateListener(({ dirtyElements }) => {
            if (dirtyElements.size > 0)
                updateTextDirection(editor, textDirection);
        });
    }, [editor, textDirection]);
}
function updateTextDirection(editor, textDirection) {
    if (textDirection === "auto")
        return;
    const rootElement = editor.getRootElement();
    if (rootElement)
        rootElement.dir = textDirection;
    const placeholderClassName = editor._config.theme.placeholder;
    const placeholderElement = document.getElementsByClassName(placeholderClassName)[0];
    if (placeholderElement)
        placeholderElement.dir = textDirection;
}
