/**
 * Models for the rich-text Operational Transform documents used in Scripture Forge.
 * `OT_???_PROPS` are the properties that can be set on the corresponding Lexical node. The rest go
 *   into unknownAttributes.
 */
export const OT_PARA_PROPS = ["style"];
export const OT_BOOK_PROPS = ["style", "code"];
export const OT_CHAR_PROPS = ["style", "cid"];
export const OT_CHAPTER_PROPS = [
    "style",
    "number",
    "sid",
    "altnumber",
    "pubnumber",
];
export const OT_VERSE_PROPS = [
    "style",
    "number",
    "sid",
    "altnumber",
    "pubnumber",
];
export const OT_MILESTONE_PROPS = [
    "style",
    "sid",
    "eid",
    "attributeOrder",
];
// Note that `contents` is not a property of a NoteNode, but we don't want it in unknownAttributes.
export const OT_NOTE_PROPS = ["style", "caller", "category", "contents"];
export const OT_UNKNOWN_PROPS = ["tag", "marker", "contents"];
export const validOTEmbedTypes = [
    "chapter",
    "immutable-chapter",
    "verse",
    "immutable-verse",
    "ms",
    "note",
    "unknown",
    "unmatched",
];
